properties.query:
// Source: QRadar — Multiple Failed Logins
let lookback = ago(1h);
let threshold = 5;
SecurityEvent
| where TimeGenerated >= lookback
| where EventID == 4625
| where AccountName !endswith "$"
| summarize FailureCount = count() by AccountName, IpAddress, Computer
| where FailureCount > threshold
| project AccountName, IpAddress, Computer, FailureCount
